python3 -c "
import json
d = json.load(open('/root/.nanobot/providers_models.json'))
# Print structure
if isinstance(d, dict):
    print('Keys:', list(d.keys()))
    models = d.get('models', [])
    print(f'Total models: {len(models)}')
    # Find claude models
    for m in models:
        mid = m.get('id','') if isinstance(m, dict) else str(m)
        if 'claude' in mid.lower() or 'anthropic' in mid.lower():
            print(m if isinstance(m, dict) else mid)
elif isinstance(d, list):
    print(f'Total models: {len(d)}')
    for m in d:
        mid = m.get('id','') if isinstance(m, dict) else str(m)
        if 'claude' in mid.lower() or 'anthropic' in mid.lower():
            print(m)
"
